"""Full registered development analysis; no outcome-based model selection."""
import collections,csv,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from run_observable import registration,identity,atomic

def main():
 reg=registration('development');rows=json.loads((ROOT/'results/observable_development_manifest.json').read_text());assert len(rows)==len(reg['configs'])==112
 assert len({r['configuration_key']for r in rows})==112 and {r['configuration_key']for r in rows}=={identity(c)for c in reg['configs']}
 assert all(r['audit']['transaction_guard_and_exposure']['status']=='passed'and r['audit']['status']=='passed'and r['audit']['aligned_reward_and_budget']['status']=='passed'and r['audit']['safety_and_cost']['status']=='passed'and r['audit']['observable_control']['status']=='passed'for r in rows)
 metrics=[]
 for r in rows:
  steps=json.loads((ROOT/r['evidence_directory']/(r['id']+'.controller.json')).read_text())['steps'];known=sum(s['event']['settled_service']['known']for s in steps);audit=r['audit']['aligned_reward_and_budget'];safety=r['audit']['safety_and_cost'];tx=r['audit']['transaction_guard_and_exposure']
  metrics.append(dict(configuration_key=r['configuration_key'],topology=r['topology'],scene=r['scenario'],seed=r['seed'],model=r['model'],profile=r['profile'],service=r['worst_party_timely'],control_bytes=r['native']['control_psdu_bytes'],ack_bytes=r['native']['ack_psdu_bytes'],radio_joules=r['estimated_radio_joules'],mac_jobs=r['audit']['mac_jobs'],known_fraction=known/len(steps),known=known,snapshots=len(steps),decisions=len(r['decisions']),trained=sum(d['selection_rule']=='linucb_score'and sum(d['updates_before_selection'])>0 for d in r['decisions']),valid_rewards=sum(f['reward']is not None for f in r['feedbacks']),censored_rewards=sum(f.get('censored',False)for f in r['feedbacks']),safety_interrupts=safety['safety_interrupts'],install_allocations=safety['install_allocations'],reserved_install_DATA_bytes=safety['reserved_install_DATA_bound_bytes'],actual_install_DATA_bytes=safety['actual_install_DATA_bytes'],cost_lower_bound_end=r['cost_observations'][-1]['observed_control_data_lower_bound']if r['cost_observations']else None,mixed_route_reward_packets=audit['mixed_route_reward_packets'],report_budget_admissions=audit['reservations_admitted'],report_budget_rejections=audit['reservations_rejected'],extra_report_data_bytes=r['audit']['report_recovery']['extra_report_data_bytes'],guard_checks=tx['two_source_guard_checks'],guard_blocks=tx['guard_blocks'],event_exploration_attempts=tx['event_exploration_attempts'],selected_reward_actions=tx['selected_reward_actions'],unconfirmed_installation_exits=r['audit']['observable_control']['unconfirmed_installation_exits'],late_installation_reconciliations=r['audit']['observable_control']['late_installation_reconciliations'],local_report_admissions=r['audit']['observable_control']['local_report_admissions'],relay_reports_emitted=r['audit']['observable_control']['relay_reports_emitted'],relay_report_ticks=r['audit']['observable_control']['relay_report_ticks']))
 by={(r['topology'],r['scene'],r['seed'],r['model'],r['profile']):r for r in metrics};native={r['configuration_key']:r for r in rows};contrasts=[]
 def compare(scene,left,right):
  pairs=[]
  for t in('base','jitter_b'):
   for seed in(1001001,1001002):
    a=by[t,scene,seed,*left];b=by[t,scene,seed,*right];ar=native[a['configuration_key']];br=native[b['configuration_key']];assert ar['hashes']['arrivals']==br['hashes']['arrivals']and ar['hashes']['positions']==br['hashes']['positions']
    pairs.append(dict(topology=t,seed=seed,service_delta=a['service']-b['service'],control_reduction=1-a['control_bytes']/b['control_bytes'],known_fraction_delta=a['known_fraction']-b['known_fraction']))
  result=dict(scene=scene,target=list(left),baseline=list(right),pairs=pairs,**{f'mean_{k}':sum(p[k]for p in pairs)/len(pairs)for k in('service_delta','control_reduction','known_fraction_delta')},topology_service_deltas={t:sum(p['service_delta']for p in pairs if p['topology']==t)/2 for t in('base','jitter_b')});contrasts.append(result);return result
 primary=[];gates=[];g=reg['gates']
 for scene in('multi_failure','overload'):
  target=('stable6','obs_full');report=compare(scene,target,('stable6','obs_no_report_retry'));reportbudget=compare(scene,target,('stable6','obs_fixed_retry'));safety=compare(scene,target,('stable6','obs_no_interrupt'));installbudget=compare(scene,target,('stable6','obs_no_install_budget'));prior=compare(scene,target,('stable6','legacy_retry8'))
  context=compare(scene,target,('intercept6','obs_full'));rule=compare(scene,target,('rule','obs_full'));resource=compare(scene,target,('resource','obs_full'))
  for other in('frozen','random'):compare(scene,target,(other,'obs_full'))
  exit_comparison=compare(scene,target,('stable6','obs_old_deadline'));exposure=compare(scene,target,('stable6','obs_exposure4'));ordinary=compare(scene,target,('stable6','obs_legacy_reports'))
  checks=dict(report_service=report['mean_service_delta']>=g['service_margin_vs_no_retry'],report_control=report['mean_control_reduction']>=-g['control_increase_limit_vs_no_retry'],observability=report['mean_known_fraction_delta']>=g['known_service_fraction_gain_vs_no_retry'],report_budget_service=reportbudget['mean_service_delta']>=g['service_margin_vs_fixed_retry'],report_budget_savings=reportbudget['mean_control_reduction']>=g['control_reduction_minimum_vs_fixed_retry'],safety_service=safety['mean_service_delta']>=g['safety_service_margin_vs_no_interrupt'],install_budget_service=installbudget['mean_service_delta']>=g['installation_budget_service_margin'],install_budget_savings=installbudget['mean_control_reduction']>=g['installation_budget_control_reduction_minimum'],rule_service=rule['mean_service_delta']>=g['rule_service_margin'],resource_service=resource['mean_service_delta']>=g['resource_service_margin'],context_gain=(context['mean_service_delta']>=g['context_service_gain']and context['mean_control_reduction']>=-g['context_cost_increase_limit'])or(context['mean_service_delta']>=g['context_alternative_service_margin']and context['mean_control_reduction']>=g['context_alternative_control_reduction']),per_topology=all(v>=g['worst_topology_service_margin']for c in(report,reportbudget,safety,installbudget,context,rule,resource)for v in c['topology_service_deltas'].values()))
  checks.update(ordinary_reporting_service=ordinary['mean_service_delta']>=reg['additional_component_gates']['ordinary_reporting_service_margin'],ordinary_reporting_savings=ordinary['mean_control_reduction']>=reg['additional_component_gates']['ordinary_reporting_control_reduction'],explicit_exposure_service=exposure['mean_service_delta']>=reg['additional_component_gates']['explicit_exposure_service_margin'],installation_exit_service=exit_comparison['mean_service_delta']>=reg['additional_component_gates']['installation_exit_service_margin'])
  runs=[by[t,scene,seed,'stable6','obs_full']for t in('base','jitter_b')for seed in(1001001,1001002)];primary.extend(runs);gates.append(dict(scene=scene,checks=checks,passed=all(checks.values()),trained=sum(r['trained']for r in runs)))
 qualification=all(m['mixed_route_reward_packets']==0 for m in metrics);accounting=all(r['audit']['safety_and_cost']['status']=='passed'for r in rows)
 opportunity=sum(m['trained']for m in primary)>=g['primary_trained_score_choices_minimum']and all(m['trained']>=g['trained_choices_minimum_per_primary_run']for m in primary)
 censors=collections.Counter();interrupt_reasons=collections.Counter()
 for r in rows:
  if r['model']=='stable6'and r['profile']=='obs_full':
   censors.update(f['missing_reason']for f in r['feedbacks']if f['reward']is None);interrupt_reasons.update(e['reason']for e in r['safety_events'])
 result=dict(complete=True,cases=112,formal_validation=False,primary=reg['primary'],comparisons=contrasts,gates=gates,qualification_gate=qualification,observable_cost_gate=accounting,opportunity_gate=opportunity,primary_trained_choices=sum(m['trained']for m in primary),primary_metrics=primary,primary_censoring_reasons=dict(censors),primary_interrupt_reasons=dict(interrupt_reasons),native_mac_jobs=sum(m['mac_jobs']for m in metrics),total_budget_rejections=sum(m['report_budget_rejections']for m in metrics),formal_matrix_admitted=qualification and accounting and opportunity and all(x['passed']for x in gates),ready_to_submit=False,LLM_runtime_calls=0)
 atomic(ROOT/'analysis/observable_analysis.json',result)
 with(ROOT/'analysis/observable_metrics.csv').open('w',newline='')as f:w=csv.DictWriter(f,fieldnames=list(metrics[0]));w.writeheader();w.writerows(metrics)
 print(json.dumps({k:v for k,v in result.items()if k not in('comparisons','primary_metrics')}))
if __name__=='__main__':main()
